import { NextResponse } from "next/server";

// RSS feeds are generated by pipeline/feeds and stored in the public Supabase Storage bucket `feeds`.
// /feed/alerts.xml redirects there, so feed readers can subscribe to a stable dashboard URL.
export async function GET(_req: Request, { params }: { params: Promise<{ name: string }> }) {
  const { name } = await params;
  const base = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const file = name.endsWith(".xml") ? name : `${name}.xml`;
  if (!/^[a-z0-9-]+\.xml$/.test(file)) return new NextResponse("Not found", { status: 404 });
  if (!base) return new NextResponse("Feeds are served from Supabase Storage; NEXT_PUBLIC_SUPABASE_URL is not set.", { status: 503 });
  return NextResponse.redirect(`${base.replace(/\/$/, "")}/storage/v1/object/public/feeds/${file}`, 307);
}
